import{_ as e,o as n,c as t,a2 as d}from"./chunks/framework.DtFGJNng.js";const k=JSON.parse('{"title":"Alur kerja","description":"","frontmatter":{},"headers":[],"relativePath":"alur-kerja.md","filePath":"alur-kerja.md","lastUpdated":1794463556000}'),i={name:"alur-kerja.md"};function s(r,a,o,l,p,u){return n(),t("div",null,[...a[0]||(a[0]=[d(`<h1 id="alur-kerja" tabindex="-1">Alur kerja <a class="header-anchor" href="#alur-kerja" aria-label="Permalink to &quot;Alur kerja&quot;">​</a></h1><p>Halaman ini menjelaskan bagaimana pekerjaan mengalir di deuz: jalur mana yang dipakai, siapa mengerjakan apa, dan kapan sebuah dokumen dilewati.</p><h2 id="langkah-pertama-tentukan-jenis-dan-dampak" tabindex="-1">Langkah pertama: tentukan jenis dan dampak <a class="header-anchor" href="#langkah-pertama-tentukan-jenis-dan-dampak" aria-label="Permalink to &quot;Langkah pertama: tentukan jenis dan dampak&quot;">​</a></h2><p>Setiap work dimulai dengan dua pertanyaan:</p><ol><li><strong>Jenisnya apa?</strong> <code>feature</code>, <code>enhancement</code>, <code>bug</code>, <code>tech</code>, atau <code>chore</code>.</li><li><strong>Apakah mengubah sesuatu yang dimiliki bisnis?</strong> Contohnya aturan harga, aturan akses, perhitungan yang dilihat pengguna, atau proses operasional.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─ triage: ada dampak bisnis? ─┐</span></span>
<span class="line"><span> feature ──────────▶│                              │</span></span>
<span class="line"><span> bug/enhancement ──▶│  ya → jalur analyst          │  tidak → jalur engineer</span></span>
<span class="line"><span> tech/chore ───────────────────────────────────────┴──▶ (langsung)</span></span></code></pre></div><ul><li><strong><code>feature</code></strong> selalu lewat jalur analyst.</li><li><strong><code>bug</code> dan <code>enhancement</code></strong> didiskusikan dulu antara engineer dan analyst. Kalau berdampak bisnis, lewat jalur analyst. Kalau tidak, lewat jalur engineer, dan hasil diskusinya dicatat di baris <code>Triage:</code> di proposal.</li><li><strong><code>tech</code> dan <code>chore</code></strong> yang murni teknis langsung lewat jalur engineer.</li></ul><p>Yang menentukan perlu gate atau tidak adalah dampaknya, bukan labelnya. Keputusan &quot;tidak perlu gate&quot; tetap meninggalkan jejak.</p><h2 id="jalur-analyst" tabindex="-1">Jalur analyst <a class="header-anchor" href="#jalur-analyst" aria-label="Permalink to &quot;Jalur analyst&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proposal ──[Gate 1: analyst + business]──▶ specs ──[Gate 2*: analyst + business]──▶</span></span>
<span class="line"><span>  ui-design ──▶ api-contract ──▶ tasks-backend ∥ tasks-frontend ∥ tasks-test ──▶ archive</span></span>
<span class="line"><span></span></span>
<span class="line"><span>* Gate 2 hanya ada bila proposal mencentang business-rules</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Langkah</th><th>Siapa</th><th>Yang dikerjakan</th><th>Konfirmasi</th></tr></thead><tbody><tr><td>1. Proposal</td><td>Analyst</td><td>Bagian bisnis (ringkasan, tujuan, scope, risiko, pertanyaan) dan jembatan teknis (capabilities, area)</td><td><code>--as analyst</code>, lalu <code>--as business</code> setelah rapat</td></tr><tr><td>2. Specs</td><td>Analyst</td><td>Requirement dan scenario per capability, dalam bahasa bisnis</td><td><code>--as analyst</code>, plus <code>--as business</code> bila ada Gate 2</td></tr><tr><td>3. UI design</td><td>Designer</td><td>Layar untuk setiap scenario yang terlihat pengguna</td><td><code>--as designer</code></td></tr><tr><td>4. API contract</td><td>Backend + frontend</td><td>Endpoint, request, response, error, hak akses</td><td><code>--as backend</code> dan <code>--as frontend</code></td></tr><tr><td>5. Tasks</td><td>Backend, frontend, QA</td><td>Keputusan teknis dan task dengan cara verifikasinya. QA juga memetakan scenario ke test</td><td>Masing-masing</td></tr><tr><td>6. Implementasi</td><td>Backend, frontend, QA</td><td><code>/deuz:apply</code>, centang task yang sudah terbukti</td><td>(tidak ada)</td></tr><tr><td>7. Archive</td><td>Siapa saja</td><td><code>/deuz:archive</code></td><td>(tidak ada)</td></tr></tbody></table><h2 id="jalur-engineer" tabindex="-1">Jalur engineer <a class="header-anchor" href="#jalur-engineer" aria-label="Permalink to &quot;Jalur engineer&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proposal (Type, Why, What changes, Triage) ──▶ [specs di-skip] ──▶ tasks ──▶ archive</span></span></code></pre></div><p>Contoh: bug &quot;tombol pesan tidak aktif setelah refresh&quot;. Spec sudah menyatakan tombol harus aktif, jadi perilakunya tidak berubah. Proposal tidak mencantumkan capability, sehingga <code>specs</code> di-skip. Area yang dicentang hanya <code>frontend</code>, sehingga <code>ui-design</code>, <code>api-contract</code>, dan <code>tasks-backend</code> juga di-skip.</p><p>Kalau bug ternyata <strong>mengubah</strong> perilaku yang tertulis di spec, proposal mencantumkan capability itu dan delta-nya memakai <code>MODIFIED</code>. Contohnya ada di <a href="./contoh">Contoh</a>.</p><h2 id="tugas-tiap-peran" tabindex="-1">Tugas tiap peran <a class="header-anchor" href="#tugas-tiap-peran" aria-label="Permalink to &quot;Tugas tiap peran&quot;">​</a></h2><p><strong>Analyst (Product System Analyst)</strong></p><ul><li>Memimpin triage dan menulis proposal serta specs.</li><li>Menyiapkan dan memimpin rapat persetujuan, lalu mencatat hasilnya.</li><li>Menjaga aturan bisnis hanya ditulis di spec.</li></ul><p><strong>Business (stakeholder)</strong></p><ul><li>Membaca proposal saat rapat, dan specs bila ada Gate 2.</li><li>Tidak menjalankan deuz. Analyst yang mencatat keputusannya.</li></ul><p><strong>Designer</strong></p><ul><li>Menerjemahkan setiap scenario yang terlihat pengguna menjadi layar.</li><li>Kalau sebuah scenario tidak bisa ditampilkan, menghentikan pekerjaan dan mengembalikannya ke analyst. Designer tidak menambah perilaku sendiri.</li></ul><p><strong>Backend dan frontend</strong></p><ul><li>Menyepakati <code>api-contract</code> bersama. Satu dokumen, dua pemilik.</li><li>Menulis <code>tasks-backend</code> dan <code>tasks-frontend</code> dengan bagian <em>Technical decisions</em> di atasnya.</li><li>Mengerjakan task lewat <code>/deuz:apply</code>. Task promote (kontrak ke definisi API, desain ke home desain) ada di urutan terakhir.</li></ul><p><strong>QA</strong></p><ul><li>Menulis <code>tasks-test</code> yang diawali coverage map: setiap scenario dipetakan ke id test.</li><li><code>deuz validate</code> memastikan tidak ada scenario yang terlewat.</li></ul><h2 id="kapan-artifact-di-skip" tabindex="-1">Kapan artifact di-skip <a class="header-anchor" href="#kapan-artifact-di-skip" aria-label="Permalink to &quot;Kapan artifact di-skip&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Penyebab</th><th>Contoh</th><th>Artifact yang di-skip</th></tr></thead><tbody><tr><td>Tidak ada peran aktif pemiliknya</td><td>Tim tanpa designer</td><td><code>ui-design</code> di setiap work</td></tr><tr><td>Area tidak dicentang di proposal</td><td>Tidak ada perubahan layar</td><td><code>ui-design</code></td></tr><tr><td></td><td>Bentuk API tidak berubah</td><td><code>api-contract</code></td></tr><tr><td></td><td>Tidak ada kode backend yang berubah</td><td><code>tasks-backend</code></td></tr><tr><td>Tidak ada capability dan tidak ada delta</td><td>Bug fix yang mengembalikan perilaku sesuai spec</td><td><code>specs</code></td></tr></tbody></table><p>Artifact yang di-skip tetap dianggap memenuhi syarat untuk artifact sesudahnya.</p><h2 id="solo-dan-tim" tabindex="-1">Solo dan tim <a class="header-anchor" href="#solo-dan-tim" aria-label="Permalink to &quot;Solo dan tim&quot;">​</a></h2><p>Kedua mode memakai artifact yang sama:</p><ul><li><strong>Solo:</strong> satu orang memegang semua peran dan mengonfirmasi sekaligus, misalnya <code>/deuz:ready api-contract --as backend,frontend</code>.</li><li><strong>Tim:</strong> setiap orang mengonfirmasi perannya sendiri. <code>/deuz:status</code> selalu menunjukkan siapa yang sedang ditunggu.</li></ul><p>Work yang dimulai solo bisa diserahkan ke tim tanpa konversi. Cara memadukannya dengan branch dan pull request ada di <a href="./tim-dan-git">Tim dan Git</a>.</p><h2 id="mengubah-dokumen-yang-sudah-ready" tabindex="-1">Mengubah dokumen yang sudah ready <a class="header-anchor" href="#mengubah-dokumen-yang-sudah-ready" aria-label="Permalink to &quot;Mengubah dokumen yang sudah ready&quot;">​</a></h2><p>Boleh, karena perubahan memang terjadi. Tapi deuz membuatnya terlihat:</p><ol><li>Dokumen yang diubah kembali <code>draft</code>, dan pemiliknya harus mengonfirmasi ulang.</li><li>Dokumen yang bergantung padanya tetap <code>ready</code>, tapi diberi tanda <em>recheck</em>. Pemiliknya perlu memastikan isinya masih berlaku.</li></ol><p>Kalau perubahan menyangkut keputusan di dokumen sebelumnya (perilaku baru, layar baru, endpoint baru), ubah dokumen sebelumnya itu. Jangan menambalnya di dokumen sesudahnya.</p>`,37)])])}const g=e(i,[["render",s]]);export{k as __pageData,g as default};
